namespace sv_700df04c26d04465978c411958bb0ccd.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    // Static list of available warehouses (shared across all circuits).
    public static readonly Dictionary<string, string> Warehouses = new()
    {
        ["WH-001"] = "Warehouse A – East",
        ["WH-002"] = "Warehouse B – West",
        ["WH-003"] = "Warehouse C – Central",
    };

    /// <summary>Raised when the selected warehouse changes. Subscribers must
    /// call <c>InvokeAsync(StateHasChanged)</c> because the event may fire
    /// from a non-render context.</summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_700df04c26d04465978c411958bb0ccd.Services;

/// <summary>
/// Scoped (per-circuit) service that polls for low-stock alerts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    /// <summary>Raised on the timer thread – subscribers must marshal to
    /// the render context with <c>InvokeAsync(StateHasChanged)</c>.</summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16)); // 0–15
    }

    /// <summary>Call when a component mounts that needs live alerts.
    /// Starts the polling timer on the first subscriber.</summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
            StartPolling();
    }

    /// <summary>Call when a component disposes.
    /// Stops the timer when no subscribers remain.</summary>
    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
            StopPolling();
    }

    private void StartPolling()
    {
        // Fire immediately, then every 10 seconds.
        _timer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollAsync()
    {
        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    /// <summary>When the warehouse changes, immediately re-poll so all
    /// subscribers see data for the newly selected site.</summary>
    private async void OnWarehouseChanged()
    {
        if (_timer is not null)
            await PollAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        StopPolling();
    }
}

